effect.shader:
const float PI = 3.14159265358979;
// Calibrados no benchmark (tools/cosmic/benchmark):
const float SIGMA_M0 = 12.0, SIGMA_M1 = 24.0;    // o borrão do Rounding: σ = 12 + 24 × Rounding/100 px
const float K_SOFT = 0.34;                        // Softness: σ = 0,34 × Softness px
const float TURB = 0.00035;                        // Turbulence: desvio de t por unidade de Amount
const float TURB_ESCALA = 80.0;                   // o tamanho do ruído: 40 px × Size
const float GLOW_A0 = 0.2592, GLOW_A = 0.3437, GLOW_C0 = -1.864, GLOW_C1 = 0.5, GLOW_S = 4.0;   // pesos do glow e o corte
const float HALO_A0 = 2.98, HALO_A = 0.96, HALO_C0 = 0.204, HALO_C1 = 0.725, HALO_S = 2.907;
const float GRAO = 0.153;                          // grão: desvio = 0,13 × Amount/100 × √cor
const float K_DIF = 0.32;                         // Optical Diffusion: σ = 0,32 × Blur px

const vec3 PRESETS[55] = vec3[55](
    vec3(0.0118, 0.0216, 0.0807), vec3(0.0294, 0.1786, 0.5181), vec3(0.0999, 0.5493, 0.9197), vec3(0.4471, 0.8482, 0.9990), vec3(0.9230, 0.9941, 1.0000),
    vec3(0.8493, 0.0412, 0.1909), vec3(0.9689, 0.7713, 0.8072), vec3(0.7900, 0.6949, 0.5462), vec3(0.1508, 0.5459, 0.4935), vec3(0.0881, 0.1976, 0.5269),
    vec3(0.9503, 0.9385, 0.9618), vec3(0.3294, 0.4546, 0.4587), vec3(0.6597, 0.7461, 0.7421), vec3(0.0245, 0.1419, 0.1383), vec3(0.3851, 0.5307, 0.4443),
    vec3(0.9842, 1.0000, 0.9999), vec3(0.9219, 0.7892, 0.7538), vec3(0.8318, 0.5151, 0.5737), vec3(0.7177, 0.2152, 0.2121), vec3(0.8110, 0.6647, 0.4880),
    vec3(0.1586, 0.0515, 0.5479), vec3(0.2151, 0.0664, 0.7497), vec3(0.0955, 0.0552, 0.3504), vec3(0.0244, 0.0462, 0.1489), vec3(0.9495, 0.2943, 0.2934),
    vec3(0.8326, 0.5507, 0.9490), vec3(0.2208, 0.2550, 0.9490), vec3(0.2389, 0.3449, 0.9490), vec3(0.2390, 0.4730, 0.9490), vec3(0.4923, 0.9059, 0.9490),
    vec3(0.5026, 0.0000, 0.5011), vec3(0.6617, 0.0000, 0.4478), vec3(0.8351, 0.0000, 0.2827), vec3(0.9169, 0.0000, 0.1421), vec3(1.0000, 0.0000, 0.0000),
    vec3(0.7693, 0.8828, 0.9994), vec3(0.0175, 0.4007, 0.7493), vec3(0.0111, 0.6221, 0.8557), vec3(0.0205, 0.7581, 0.2845), vec3(0.0013, 0.4422, 0.1582),
    vec3(0.9497, 0.7174, 0.0201), vec3(0.9483, 0.5301, 0.0194), vec3(0.9511, 0.3619, 0.0199), vec3(0.3483, 0.0082, 0.0071), vec3(0.9986, 0.2333, 0.2355),
    vec3(0.8851, 0.0273, 0.0796), vec3(0.9171, 0.3508, 0.0507), vec3(1.0000, 0.8625, 0.0549), vec3(0.0455, 0.5975, 0.2258), vec3(0.0521, 0.2521, 0.5812),
    vec3(0.9602, 0.0209, 0.2497), vec3(0.0109, 0.2877, 0.6494), vec3(0.9898, 0.7614, 0.8719), vec3(1.0000, 0.4698, 0.2294), vec3(0.9991, 0.7935, 0.0000));

vec2 tamanho() { return vec2(textureSize(inputImg, 0)); }
/** Um px da composição, em UV do quadro. */
vec2 px() { return acEscalaDePixel / tamanho(); }
float forma(vec2 uv) { return (uv.x < 0.0 || uv.y < 0.0 || uv.x > 1.0 || uv.y > 1.0) ? 0.0 : texture(inputImg, uv).a; }
float h1(vec2 p) { vec3 q = fract(vec3(p.xyx) * 0.1031); q += dot(q, q.yzx + 33.33); return fract((q.x + q.y) * q.z); }
vec3 h3(vec3 p) { p = fract(p * vec3(0.1031, 0.1030, 0.0973)); p += dot(p, p.yxz + 33.33); return fract((p.xxy + p.yxx) * p.zyx); }

// 16 bits num par de canais de 8.
vec2 emDois(float v) { v = clamp(v, 0.0, 1.0) * 65535.0; return vec2(floor(v / 256.0), mod(floor(v), 256.0)) / 255.0; }
float deDois(vec2 c) { return (floor(c.x * 255.0 + 0.5) * 256.0 + floor(c.y * 255.0 + 0.5)) / 65535.0; }

// ------------------------------------------------------------------ a paleta
// Medido: cinco cores numa volta (a última volta para a primeira), interpoladas em linha reta na cor
// do monitor. As do "Custom" ficam a 0, 20, 40, 60 e 80% da volta; os presets também, menos o 1
// (Ocean, o azul de fábrica), que tem as paradas a 0, 25, 50, 72 e 88%.
vec3 paleta(float t) {
    t = fract(t);
    vec3 c[5]; float p[5];
    int pr = colors - 1;
    if (pr < 0) { c[0] = color1.rgb; c[1] = color2.rgb; c[2] = color3.rgb; c[3] = color4.rgb; c[4] = color5.rgb; }
    else for (int i = 0; i < 5; i++) c[i] = PRESETS[pr * 5 + i];
    if (pr == 0) { p[0] = 0.0; p[1] = 0.25; p[2] = 0.5; p[3] = 0.72; p[4] = 0.88; }
    else { p[0] = 0.0; p[1] = 0.2; p[2] = 0.4; p[3] = 0.6; p[4] = 0.8; }
    for (int i = 0; i < 4; i++) if (t < p[i + 1]) return mix(c[i], c[i + 1], (t - p[i]) / (p[i + 1] - p[i]));
    return mix(c[4], c[0], (t - p[4]) / (1.0 - p[4]));
}

// ------------------------------------------------------------------ Turbulence
float ruidoGrad(vec3 p) {
    vec3 i = floor(p), f = fract(p), u = f * f * (3.0 - 2.0 * f);
    float n = 0.0;
    for (int z = 0; z < 2; z++) for (int y = 0; y < 2; y++) for (int x = 0; x < 2; x++) {
        vec3 o = vec3(float(x), float(y), float(z));
        vec3 g = normalize(h3(i + o) * 2.0 - 1.0 + 1e-4);
        vec3 w = mix(1.0 - u, u, o);
        n += w.x * w.y * w.z * dot(g, f - o);
    }
    return n;
}
float turbulencia(vec2 P) {
    vec3 q = vec3(P.x / (TURB_ESCALA * sizeX), P.y / (TURB_ESCALA * sizeY), evolution / 360.0);
    // duas oitavas; o fator leva o desvio do ruído a ~1
    return 3.2 * ruidoGrad(q);
}

// ------------------------------------------------------------------ o campo t do degradê
// Medido: t = projeção do pixel no ângulo, a partir do meio do quadro, em alturas do quadro, + 0,5;
// × Cycles (a partir de t = 0), + Offset/100 + Phase/360. O Depth soma Bulge/100 × r × m, onde r é a
// mesma rampa no ângulo do Depth, medida na CAIXA da forma (dividida pela diagonal dela) e com o
// Contrast em volta de 0,5; m é o alfa borrado (o "domo" do Rounding).
float campoT(vec2 uv) {
    vec2 R = tamanho();
    vec2 P = uv * R;
    float a = radians(angle);
    float t = (dot(P - 0.5 * R, vec2(cos(a), sin(a))) / R.y + 0.5) * cycles + offset / 100.0 + phase / 360.0;
    if (bulge != 0.0) {
        vec4 cx = texelFetch(caixa, ivec2(0, 0), 0), cy = texelFetch(caixa, ivec2(1, 0), 0);
        vec2 p0 = vec2(deDois(cx.rg), deDois(cy.rg)) * R, p1 = vec2(deDois(cx.ba), deDois(cy.ba)) * R;
        float th = radians(depthAngle);
        float r = 0.5 + dot(P - 0.5 * (p0 + p1), vec2(cos(th), sin(th))) / max(length(p1 - p0), 1.0);
        r = clamp((r - 0.5) * contrast / 100.0 + 0.5, 0.0, 1.0);
        t += bulge / 100.0 * r * texture(mv, uv).r;
    }
    if (turbulence > 0.0) t += turbulence * TURB * turbulencia(P / acEscalaDePixel);
    return t;
}

/** Saturation (luma Rec.601) e Brightness (multiplica), na cor do monitor. */
vec3 ajustar(vec3 c) {
    float y = dot(c, vec3(0.299, 0.587, 0.114));
    return clamp((y + (c - y) * saturation / 100.0) * brightness / 100.0, 0.0, 1.0);
}

float peso(float i, float n) { float x = 3.0 * i / n; return exp(-0.5 * x * x); }

/** Gaussiana separável num canal ou em todos; `volta` = borda que dá a volta (o Softness). */
vec4 borrar(sampler2D t, vec2 eixo, float sigmaPx, bool volta) {
    if (sigmaPx < 0.3) return texture(t, acScreenNorm);
    const float N = 24.0;
    vec4 soma = vec4(0.0); float tot = 0.0;
    for (float i = -N; i <= N; i += 1.0) {
        float w = peso(i, N);
        vec2 q = acScreenNorm + eixo * (3.0 * sigmaPx * i / N);
        soma += w * texture(t, volta ? fract(q) : clamp(q, 0.0, 1.0)); tot += w;
    }
    return soma / tot;
}

// ------------------------------------------------------------------ o glow
// Medido: em luz linear (gama 2,2), soma de borrões gaussianos da cor × alfa, CADA UM DIVIDIDO PELO
// PICO do próprio nível no quadro (é por isso que um ponto pequeno brilha longe e um texto grosso
// não estoura). O Radius corta os níveis acima do tamanho dele (o Falloff empurra o corte); o alfa
// da camada ganha o mesmo halo (preto) mesmo com Intensity 0.
float sigmaDoNivel(int k) { return 3.0 * exp2(float(k - 1)); }    // px: 3, 6, 12 … 768
float corte(int k, float A, float c0, float c1, float s) {
    float x = log2(sigmaDoNivel(k) / max(glowRadius, 1.0));
    float c = c0 + c1 * (50.0 - glowFalloff) / 50.0;
    return A / (1.0 + exp((x - c) * s));
}
vec4 nivel(int k, vec2 uv) {
    vec4 v = k == 1 ? texture(g1, uv) : k == 2 ? texture(g2, uv) : k == 3 ? texture(g3, uv) : k == 4 ? texture(g4, uv) :
             k == 5 ? texture(g5, uv) : k == 6 ? texture(g6, uv) : k == 7 ? texture(g7, uv) : k == 8 ? texture(g8, uv) : texture(g9, uv);
    return v * v;                         // cor e alfa vão em raiz quadrada (8 bits)
}
float picoDo(int k) { return max(deDois(texelFetch(picos, ivec2((k - 1) % 3, (k - 1) / 3), 0).rg), 1e-4); }

/** Um nível a partir do anterior (ou da imagem, no primeiro): só o σ que falta. */
vec4 descer(int k) {
    vec2 uv = acScreenNorm;
    float falta = sqrt(max(sigmaDoNivel(k) * sigmaDoNivel(k) - (k == 1 ? 0.0 : sigmaDoNivel(k - 1) * sigmaDoNivel(k - 1)), 0.0));
    vec2 passo = falta / 1.2 * px();
    vec4 soma = vec4(0.0); float tot = 0.0;
    for (int j = -3; j <= 3; j++) for (int i = -3; i <= 3; i++) {
        vec2 o = vec2(float(i), float(j));
        float w = exp(-0.5 * dot(o, o) / (1.2 * 1.2));
        vec2 q = uv + o * passo;
        vec4 v;
        if (k == 1) {
            float s = forma(q);
            vec3 c = texture(sv, clamp(q, 0.0, 1.0)).rgb;
            vec3 l = pow(c, vec3(2.2)) * s;
            // Threshold: só o que passa do limiar (em luz linear)
            l *= smoothstep(glowThreshold / 100.0, glowThreshold / 100.0 + 0.05, dot(c, vec3(0.299, 0.587, 0.114)));
            v = vec4(l, s);
        } else v = nivel(k - 1, clamp(q, 0.0, 1.0));
        soma += w * v; tot += w;
    }
    soma /= tot;
    return sqrt(soma);
}

/** O pico do alfa de um nível no quadro: os três primeiros pelos máximos em blocos (`mp`), os outros texel a texel. */
float picoDeNivel(int k) {
    float m = 0.0;
    ivec2 t = k <= 3 ? textureSize(mp, 0) : k == 4 ? textureSize(g4, 0) : k == 5 ? textureSize(g5, 0) : k == 6 ? textureSize(g6, 0) : k == 7 ? textureSize(g7, 0) : k == 8 ? textureSize(g8, 0) : textureSize(g9, 0);
    for (int j = 0; j < 128; j++) {
        if (j >= t.y) break;
        for (int i = 0; i < 256; i++) {
            if (i >= t.x) break;
            ivec2 q = ivec2(i, j);
            vec4 v = k <= 3 ? texelFetch(mp, q, 0) : k == 4 ? texelFetch(g4, q, 0) : k == 5 ? texelFetch(g5, q, 0) : k == 6 ? texelFetch(g6, q, 0) : k == 7 ? texelFetch(g7, q, 0) : k == 8 ? texelFetch(g8, q, 0) : texelFetch(g9, q, 0);
            float a = k == 1 ? v.r : k == 2 ? v.g : k == 3 ? v.b : v.a;
            m = max(m, a * a);
        }
    }
    return m;
}

/** O máximo (em raiz) do alfa dos níveis 1, 2 e 3 em cada bloco deste buffer. */
vec4 maximosEmBloco() {
    vec3 m = vec3(0.0);
    ivec2 o = ivec2(gl_FragCoord.xy);
    for (int j = 0; j < 8; j++) for (int i = 0; i < 8; i++) {
        m.r = max(m.r, texelFetch(g1, min(o * 8 + ivec2(i, j), textureSize(g1, 0) - 1), 0).a);
        if (i < 4 && j < 4) m.g = max(m.g, texelFetch(g2, min(o * 4 + ivec2(i, j), textureSize(g2, 0) - 1), 0).a);
        if (i < 2 && j < 2) m.b = max(m.b, texelFetch(g3, min(o * 2 + ivec2(i, j), textureSize(g3, 0) - 1), 0).a);
    }
    return vec4(m, 1.0);
}

void main() {
    vec2 uv = acScreenNorm;
    vec2 p = px();

    if (acPass == 0) {
        // a caixa da forma, numa grade de 240 × 135: cada texel varre a SUA linha j e guarda a primeira e a última
        // coluna com alfa. Até a 0.659 dois pixels varriam a grade inteira em fila (8–9 ms na GPU do PC, quase tudo
        // espera); agora são 135 linhas ao mesmo tempo e a junção (abaixo) lê 135 texels.
        int j = int(gl_FragCoord.x);
        int primeira = -1, ultima = -1;
        for (int i = 0; i < 240; i++) {
            vec2 q = (vec2(float(i), float(j)) + 0.5) / vec2(240.0, 135.0);
            if (texture(inputImg, q).a > 0.004) { if (primeira < 0) primeira = i; ultima = i; }
        }
        fragColor = primeira < 0 ? vec4(0.0) : vec4(float(primeira), float(ultima), 255.0, 255.0) / 255.0;
        return;
    }
    if (acPass == 1) {
        // a caixa: a junção das linhas. As contas de cada canto são as de antes, no mesmo ponto da grade — o menor de
        // q − meio texel numa linha é o da primeira coluna (a conta só cresce com a coluna), e o maior, o da última.
        ivec2 o = ivec2(gl_FragCoord.xy);
        if (o.y != 0 || o.x > 1) { fragColor = vec4(0.0); return; }
        vec2 mn = vec2(1.0), mx = vec2(0.0);
        for (int j = 0; j < 135; j++) {
            vec4 l = texelFetch(linhas, ivec2(j, 0), 0);
            if (l.b < 0.5) continue;
            int primeira = int(l.r * 255.0 + 0.5), ultima = int(l.g * 255.0 + 0.5);
            vec2 q0 = (vec2(float(primeira), float(j)) + 0.5) / vec2(240.0, 135.0);
            vec2 q1 = (vec2(float(ultima), float(j)) + 0.5) / vec2(240.0, 135.0);
            mn = min(mn, q0 - 0.5 / vec2(240.0, 135.0)); mx = max(mx, q1 + 0.5 / vec2(240.0, 135.0));
        }
        if (mx.x < mn.x) { mn = vec2(0.0); mx = vec2(1.0); }
        fragColor = o.x == 0 ? vec4(emDois(mn.x), emDois(mx.x)) : vec4(emDois(mn.y), emDois(mx.y));
        return;
    }
    float sm = SIGMA_M0 + SIGMA_M1 * rounding / 100.0;
    if (acPass == 2) {
        const float N = 20.0;
        float soma = 0.0, tot = 0.0;
        for (float i = -N; i <= N; i += 1.0) { float w = peso(i, N); soma += w * forma(uv + vec2(3.0 * sm * i / N * p.x, 0.0)); tot += w; }
        fragColor = vec4(soma / tot, 0.0, 0.0, 1.0); return;
    }
    if (acPass == 3) { fragColor = vec4(borrar(mh, vec2(0.0, p.y), sm, false).r, 0.0, 0.0, 1.0); return; }
    if (acPass == 4) { fragColor = vec4(ajustar(paleta(campoT(uv))), 1.0); return; }
    float ss = K_SOFT * softness;
    if (acPass == 5) { fragColor = borrar(cor, vec2(p.x, 0.0), ss, true); return; }
    if (acPass == 6) { fragColor = borrar(sh, vec2(0.0, p.y), ss, true); return; }
    if (acPass >= 7 && acPass <= 15) { fragColor = descer(acPass - 6); return; }
    if (acPass == 16) { fragColor = maximosEmBloco(); return; }
    if (acPass == 17) {
        ivec2 o = ivec2(gl_FragCoord.xy);
        if (o.x > 2 || o.y > 2) { fragColor = vec4(0.0); return; }
        fragColor = vec4(emDois(picoDeNivel(o.y * 3 + o.x + 1)), 0.0, 1.0); return;
    }
    if (acPass == 18) {
        float s = forma(uv);
        vec3 c = texture(sv, uv).rgb;
        vec3 l = pow(c * s, vec3(2.2));       // medido: a borda suave da forma escurece a cor na cor do monitor
        vec3 brilho = vec3(0.0);
        float resto = 1.0 - s;
        for (int k = 1; k <= 9; k++) {
            vec4 n = nivel(k, uv);
            float pk = picoDo(k);
            brilho += corte(k, k == 1 ? GLOW_A0 : GLOW_A, GLOW_C0, GLOW_C1, GLOW_S) * n.rgb / pk;
            resto *= 1.0 - clamp(corte(k, k == 1 ? HALO_A0 : HALO_A, HALO_C0, HALO_C1, HALO_S) * n.a / pk, 0.0, 1.0);
        }
        vec3 luz = l + glowIntensity / 100.0 * brilho;
        // Soft Clip: comprime o que passa de 1 em vez de cortar
        float sc = softClip / 100.0;
        if (sc > 0.0) luz = mix(luz, luz / (1.0 + luz), sc);
        vec3 corFinal = pow(clamp(luz, 0.0, 1.0), vec3(1.0 / 2.2));
        // a cor já vem "por cima de preto" (premultiplicada); o alfa nunca fica abaixo dela
        float alfa = max(1.0 - resto, max(corFinal.r, max(corFinal.g, corFinal.b)));
        fragColor = vec4(corFinal, alfa);
        return;
    }
    // Optical Diffusion: σ = 0,32 × Blur × smoothstep(Focus, Focus + Feather, distância ao Center)
    float sd = K_DIF * diffusion;
    if (acPass == 19) { fragColor = borrar(nitido, vec2(p.x, 0.0), 0.5 * sd, false); return; }
    if (acPass == 20) { fragColor = borrar(d1h, vec2(0.0, p.y), 0.5 * sd, false); return; }
    if (acPass == 21) { fragColor = borrar(nitido, vec2(p.x, 0.0), sd, false); return; }
    if (acPass == 22) { fragColor = borrar(d2h, vec2(0.0, p.y), sd, false); return; }

    vec2 R = tamanho();
    float dist = length((uv - center) * R) / acEscalaDePixel;
    float w = smoothstep(focus, focus + max(feather, 1e-3), dist);
    if (invert) w = 1.0 - w;
    vec4 n0 = texture(nitido, uv), n1 = texture(d1, uv), n2 = texture(d2, uv);
    vec4 r = sd < 0.3 ? n0 : (w < 0.5 ? mix(n0, n1, w * 2.0) : mix(n1, n2, w * 2.0 - 1.0));
    vec3 c = r.a > 1e-4 ? min(r.rgb / r.a, 1.0) : vec3(0.0);

    // Grain: ruído por canal (o Color mistura com um ruído só para os três), proporcional a √cor
    if (grain > 0.0) {
        float quadro = grainAnimate ? floor(acTime * 30.0 + 0.5) : 0.0;
        vec2 cel = uv * R / (acEscalaDePixel * grainSize);
        // medido: células quadradas de Size px, sem interpolação (autocorrelação 0 com 1 px, 2/3 com 3 px)
        vec2 i0 = floor(cel);
        vec3 a = h3(vec3(i0, quadro)), b = h3(vec3(i0 + 17.0, quadro + 3.0));
        // gaussiana aproximada: soma de dois uniformes
        vec4 n = vec4(a + b - 1.0, (a.x + b.y + a.z + b.x - 2.0) * 0.7071) * 2.449;
        vec3 rg = mix(vec3(n.a), n.rgb, grainColor / 100.0);
        c = clamp(c + GRAO * grain / 100.0 * sqrt(max(c, 0.0)) * rg, 0.0, 1.0);
    }
    fragColor = vec4(c, r.a);
}
